cat > /tmp/smoke/test.js <<'EOF'
const { JSDOM } = require('jsdom');
const path = require('path');
const store = {};
function load(page, cb) {
  return JSDOM.fromFile(path.join('/work', page), {
    runScripts: 'dangerously', resources: 'usable', url: 'file:///work/' + page,
    beforeParse(w) {
      w.matchMedia = () => ({ matches: false, addEventListener() {} });
      Object.defineProperty(w, 'localStorage', { value: {
        getItem: k => (k in store ? store[k] : null), setItem: (k, v) => { store[k] = String(v); } } });
      const P = w.HTMLDialogElement.prototype;
      P.showModal = function () { this.open = true; };
      P.close = function (v) { if (v !== undefined) this.returnValue = v; this.open = false; this.dispatchEvent(new w.Event('close')); };
      w.scrollTo = () => {}; w.HTMLElement.prototype.scrollIntoView = () => {};
      w.addEventListener('error', e => console.error('PAGE ERROR', page, e.message));
    }
  }).then(dom => new Promise(r => dom.window.addEventListener('load', () => setTimeout(() => r(dom), 50))));
}
const tick = (ms = 50) => new Promise(r => setTimeout(r, ms));
(async () => {
  let d = (await load('index.html')).window.document;
  console.log('home featured:', d.querySelectorAll('#featured-courses .course-card').length, 'depts:', d.querySelectorAll('.dept-tile').length);

  let dom = await load('catalog.html'); d = dom.window.document;
  console.log('catalog:', d.querySelector('#results-count').textContent);
  d.querySelector('#filter-dept').value = 'cs';
  d.querySelector('#filter-dept').dispatchEvent(new dom.window.Event('change', { bubbles: true }));
  console.log('cs filter:', d.querySelector('#results-count').textContent);
  ['CS101', 'MATH220'].forEach(id => {}); 
  d.querySelector('#filter-dept').value = '';
  d.querySelector('#search').value = 'linear';
  d.querySelector('#search').dispatchEvent(new dom.window.Event('input', { bubbles: true }));
  await tick(400);
  console.log('search linear:', d.querySelector('#results-count').textContent);
  d.querySelector('[data-id="MATH220"]').click();
  d.querySelector('#search').value = '';
  d.querySelector('#catalog-filters').dispatchEvent(new dom.window.Event('submit', { cancelable: true }));
  d.querySelector('[data-id="CS101"]').click();
  console.log('cart:', store['nbu.cart'], 'focused:', d.activeElement.textContent.trim().replace(/\s+/g, ' '));
  console.log('selection bar:', d.querySelector('#selection-text').textContent, 'badge:', d.querySelector('[data-cart-badge]').textContent);

  dom = await load('register.html'); d = dom.window.document;
  console.log('picks:', d.querySelectorAll('.pick').length, 'conflict hidden:', d.querySelector('#conflict-warning').hidden, d.querySelector('#conflict-warning li')?.textContent);
  d.querySelector('#registration-form').dispatchEvent(new dom.window.Event('submit', { cancelable: true }));
  console.log('errors:', [...d.querySelectorAll('#error-summary li')].map(l => l.textContent));
  console.log('focus on summary:', d.activeElement.id, 'title:', d.title);
  d.querySelector('#pick-MATH220').click();
  d.querySelector('#agree').click();
  d.querySelector('#registration-form').dispatchEvent(new dom.window.Event('submit', { cancelable: true }));
  await tick();
  const dlg = d.querySelector('dialog');
  console.log('dialog open:', dlg.open, '|', d.querySelector('#modal-desc').textContent);
  d.querySelector('[data-modal-confirm]').click(); // form method=dialog not handled by jsdom; close manually
  if (dlg.open) dlg.close('confirm');
  await tick();
  console.log('success shown:', !d.querySelector('#success-panel').hidden, 'focus:', d.activeElement.id, 'registered:', store['nbu.registered']);

  dom = await load('profile.html'); d = dom.window.document;
  console.log('rows:', d.querySelectorAll('#registered-body tr').length, 'credits:', d.querySelector('#total-credits').textContent, '|', d.querySelector('#credit-bar-text').textContent);
  d.querySelector('[data-drop]').click(); await tick();
  d.querySelector('dialog').close('confirm'); await tick();
  console.log('after drop rows:', d.querySelectorAll('#registered-body tr').length, 'focus:', d.activeElement.dataset.drop);
  d.querySelector('#edit-profile').click();
  d.querySelector('#pf-email').value = 'bad';
  d.querySelector('#profile-form').dispatchEvent(new dom.window.Event('submit', { cancelable: true }));
  console.log('profile errors:', d.querySelector('#profile-error-summary').textContent.trim().replace(/\s+/g, ' '), d.querySelector('#pf-email').getAttribute('aria-invalid'));
})();
EOF
cd /tmp/smoke && node test.js

